࿀༔࿄༰྾༂ཱུ༰༲༘༝࿡༈࿪ཧ༣࿬༥ཿཱིྜྷྋ༟ཱི༧༚ཨབྷིྀ༼ཹ྘྄ཿྦ࿈཮༇༃ྺེྶ࿉཭ྕཡ࿎ྖ࿼࿪ྐ࿿࿰ྙ༦ྛྭཟྜྷ༔ཤ࿹ྗ࿺༢཯ྊ྽ྏའ࿄࿼དྷཪཥ༔ཟྙ࿼༑༓ྑཤཌྷ࿚ྺ༩࿉ྭཿ࿉྄ླཹི࿫དྷྒྛ࿙༿ཪཎྔ࿖ྫྷདྷ࿲ཱུྎ࿩༿༎ཅཱ྅༁࿧ཌ࿌࿔ཚ࿹ྼ༮༛༨࿺ཽཻྡྷ࿦༂མ཯ཊཪཉྏ࿣࿙ྜྷྪༀྦྷཀཱིྦྒྠ༏་༬࿜གྷྡྷ༙ྎཿ࿧ྒྷ༚࿩༇࿣࿞࿈བྷྍ࿙༨༔࿿ྗྂ༃࿊༶ྣ༫བ࿧࿜ཞུཬ࿰࿏ུ༷࿅ྲྀ༴ཅ༰ཡ྇ཛྷ༭༠ི༿࿷྾ྊ࿧཰ྯ཮ཾ༳࿌ཙ༐ྙ཰༙࿞༤ཹྀ࿌ག࿆༕ཚ༱མ༾࿾༔ྋྤ཮༭༝ཾྻྨ࿁ྛཚ༹ྋ༙࿼ུ༙༐༽྅ྊྯ࿺༓࿀༔࿄ྊཆ༂ཱུཀྩྫྷ࿟༓࿜ྥྦྷ༣ཧྭ྽ཱིཌ༚ས࿺࿋ྮ༒༚࿪ྐ࿻ཚྣཆྜྸྱཝ࿄ཫ༟ེ࿥ཕོྕ࿗ྶྼ༮࿵ྮ࿂ྚ࿋࿬༰༛ཬྦྞབྸཚ༝࿁࿤ྒྷ࿃ྍྫྷྊཛྷ࿉࿓༒࿯ཾ༏༚༑༓࿦ྶཌྷ࿊གྷ࿖ྦ༦ཱུཆྀྦ࿊࿶ཧྡྷ࿊ྲྀྫྷྗ࿘༻࿊ཬཪྼ༢࿈ྛ࿁༒ྵཻ༁࿗࿾ྙ࿚ན࿖ླྀྐྌཨ࿻ཎྣྐྵཛྷ༎ཿ࿣ཽཔཊཻཿ༔༿༺ཆཱྀ࿯ྗཀྺྉྺ࿕࿿ྦྒྷ࿛ཞ༢࿀࿥࿅࿩༈࿁ནཛྷྻྴཻ࿩༆྽ཅ࿶ྒཱིྃ࿳࿌༻ྃྜྷྦ࿜ཉ༖྄༷༯ཛྷཱྀྦྷ࿏ྯ༴ཀ࿲ྖྏཛྷཚ࿻ཫྊེ༽࿄གྷ࿖࿁࿖࿟༳ཌྷྐདྷལ࿾࿎ྑ༤ཕཊ༥ཛྷ࿋ྼ༙࿝ྕ࿅཮ྱྭ࿵ཪ྽༴༵྘ཻ༳ྜྷ࿛ྦ࿖ཞ࿹ྶྛྋླང༱࿵༮ྰ༖༶ྫྔ྄ཫ࿮༒࿐པྶ࿣࿈༔࿕࿿࿶༣༣࿓ྉྐ༟རལ࿍ཱི༤࿽ྜ࿰ྡྷསྴྃྔ༇ཇྒ཯ྷྗ༓༒ྸ༃ྮྂྱ༄ོཷ༡༯࿋ྲྀ࿠།ཟ་࿉ཌྷ཰ྈྜཪ྄ྲྀ࿮࿎࿅ཪྨཿ༿༘ཿཱུ࿍༌ཿྻ༩ར࿼ྦྨྔ།࿧࿣ྜཅཧཤཚ༐དྷ࿸ྙཱུྠོ༿࿒ྖྟ༃࿡མ࿝ན࿀ྀ࿛ྵུཏྒྷ࿹ྊཛཱྩ྇བྷ༛ཬ༝ཛྷ࿘༸࿜ླ࿘࿜༖ྡྻ࿥ཛྷཽྙ༫ༀྐཛྷཌྷུྦྷྒྷྪྶྎྜྷཌྰ࿕࿕ཟྻྴའ࿀ཾཨ࿇༒༳࿅ྗྯ཮༉ྮ࿺࿳༲༶༄࿹༥ྋཱིྺ༼ྀབ༱ྶྭ༪࿗࿡༭ཀྵ༃࿜༪ྥྨྡཤྱ࿳༴࿥࿖༆࿖࿼༧ཌྷ།ྪཞ༗༥༳ཏྌ༚࿗ྤ་ྼྃ࿄࿮࿅༶ཨ༣࿓༆༃་࿸༄༄ཻ༩࿏࿂༳࿿྘࿆࿈མ࿓ྐ༵ྩཧ༡ུྫྷ࿛྅ྔ࿮࿳྽࿻༊࿯ླ༉༽ཧ༙ཧཞཿཱིན༸྆༫ཡ࿦ཨབྷི༭ཞ࿢྘༒༂༮ཛྷ࿣༝༔༏༊ྤༀཽ༴ཾྮ࿘࿥༉བྜ࿗ཙ༥ཞྦྷ࿸༽࿂༯ྂ࿇ཡ༶༉ཆ࿮࿎࿶ཪྨ༓༘མ࿜࿒༅ྃཿྗེཤཌྷ༅༩་ཌ༙༶࿉྄ཨ༥ི࿫࿇ཽགྷྒྡྷ༨ཎྔྤྟདཇྼ༮༜ཬ༯࿳ྏ࿴ང࿧ྲ࿉ྪ࿽ྒ༏༬༄ྊ࿗࿜ཨུ༵༾མ༢࿂ྈ཈༺༵ན྆༦ྥ༦࿮ྭ࿉ཟ࿒ད་༩࿘࿿༽ཛ༨༕ྛ࿯༢࿫ཛྷ࿎ཿ༝࿩ཫླྀྖ༔ྕ࿆ཅྈ࿥ཅ࿦ཆྜྷྪདྷ࿅གྷཬྪ࿒བྷཤ༤ཫ࿲࿤࿀གྥཻཁཚ࿟ཱ࿜࿁཮ྨ࿎࿁ྃཥ࿩ྐཟ࿀࿴࿹༟ཕ༧ྼ࿥ྨ࿙࿋࿈࿑ྡྷ༗ཬོཬ༜༽࿞ྤ྽༵࿬ཻ࿋ྜྷ࿛࿴༜ཆཏ཰ྔྋླྑ༡࿝༣ྴ࿺࿯ཛྷ྿࿈ྡ࿮ༀའ཮ཥ༺ཻ༑༙࿚ཻ༏࿡ཌྷ࿔ྺཙུཆ༆ྙ༁༞ཌྷཙྗཙྟ࿲࿫༘࿯ྕ༃ྺ༻ཇ༑࿪ྷ༲཰དྷྜྥ༐ཷྫལ࿧ྒྷ༯࿜ྜྷཇ༭བ༪ྭཟྼ༛༒གྷླ࿯ྨ࿸ེ྽ྫྷྫྷ྽༳ཀཤ༇༦༥ཞ༯༯࿂ཱྀༀ༐྄ཙ࿭ྰཾ࿃༒࿺ཎ༃࿟࿏ྃ࿃ཁ༝࿹ག༣༣࿪ལྥཧཆ༗ཏ࿫༵དཇྩཇྭགྷ༆༅༞ཻ༜ྱ࿎༸཈࿐࿙ཾ࿙࿮ྠྲ࿎࿸༷ཪཥ࿸࿨ྯ༬྘ྦྷ࿇ྔ྇࿍࿉ྑ࿻༝ྼ࿈࿄࿵࿏ྟ༁ཽ࿛࿅ྑ྽གྷ༫ཛ༬ྟ༳࿇࿆ཧ࿧ྲྀཌྷེཐ༞ྖཞྌྮ྾ༀྂ࿙ྖཻྥ࿱ྠགྷ࿘ཱུ༴༯࿥࿸ྜ࿸ྯཙྔ༅࿨།࿻࿵ཟ࿚ྋ࿭ཱོྀ࿡༇༮࿣ྐྵ࿤༴༱༊࿤ྥ࿺࿢༣༄༂࿂࿅࿋ཆྔ࿗༦༦࿊࿯༛༶༭ྑ࿽༮ི༆࿋࿃༭དྷཨ༠ཎཁ཭དྷཽཻ࿆࿾ཡ཈ྦྷྲྺཙྋ࿚ཧྑ࿌ྀ࿋ཙཬ༅ྕ༘࿪྘༔ཚདྷ࿿༑༽࿷࿢྄ྙྋ࿈࿠ཚྜ࿦ྚ࿫དྷ࿑ནཥ༳ཛྷ༗࿀ཱ࿺༉ྠ༛࿳ཫཅཱུ࿿༾཭ད࿣ྴ྘༳ཱ༹པ༛ྒྷཐ཰ཡྦ༅ཛྦྚྫྷྛག࿔༶༰༧࿲༝࿞ྠྨ࿝ཪཋ࿲࿛྿࿬࿅ཱྀ࿘ྋཀྵྩ༑࿯༌ྶ༒࿗༂ྜྷ༖ཛྷ࿐཯༾༟ཱེུ༵༿མ༆࿅ྥ༇ྒན་࿬ཇ཈ུྙ༯༜࿾࿪ྦྷ࿸ང࿙ྛཤ࿡༮ཆྦྷ་༇࿯ྫྷདྷཞྠ࿭༑཰ྒ༣ྔཁ༁࿁ཟ།ྞ༚༙࿧྆༽ྦྪ༯ྊཚ༦༺࿁࿧྾༩ཛྷ࿩ལཛ࿶྽༃༢༴࿼ྺ༩ཾྩཌྷྲ࿬࿈࿹༞ཿ࿠ཨཙ࿰ག࿡༵࿿བྷྼྍ࿷༨སྃྟ༗༶༇ཡ࿴༵࿎ཡྜྷྤྷ࿵༸྅࿨࿵༔ཹ࿙༎ིནཱཽུ༸༁༾ྮྏ࿹ྰཽ༵࿈༩࿫༵ཨཟ࿡ྜྵྩཚད༘཰༓༫ྫ࿂࿼༬྘཰ྡ྽࿁ྤ࿄ཁ༺ྠ༱ླ྆༝ྯ࿚༃཈࿁༪ྙཊ༅ྮད༷ྐྦ༎ྯྛེདྥ࿤࿄྾࿉࿞༅࿻༓࿙࿜࿉༢ཚྶ࿑࿨࿟ྐངྫྷ࿬࿮༱ཱིྫཧླྀ༚༴གའ༈༫དམ཮ོྵསབ࿣࿟ྥ༵ན༄ྒྷ࿎࿹ྣ࿠༫༧་༸ྫ࿵ྀ࿳༪ྺ༊ཡ࿪࿿༸ྃཪ༰ཽ༗ཫ࿅࿐࿈ྯ༳ཝ࿲༼࿷ཱི࿮ྩྴ༐࿾ཊ༻ྲ༞༪࿼ྵུྮ࿏ཡཅཇ࿬ཁཾ࿘༸࿈ཽཁྭ༔༃࿢࿓༓ཱིྚ༸ྲྀཎ༷࿌࿗༪༱༙཭ྭ྿࿤ཻ࿃྇࿤༒ྃྡཌྷ࿜ྂ࿇཮ཌཿ༹༘གངླ༬ྃྯ࿝༽ྉ༼༚࿏འིཎ࿣ྯ࿮ྐོས༧ཉཕ࿣༺༨མ༄࿱༣༿ྉ࿉ྲ࿧ྱ༸ྌༀ༁ྖྵཞཫཚ࿪࿱༛༴ྐྵ࿡༔࿐བྷ࿅ྷིྍཡ༤༵གྷྸཱིཛ྅ྦྷྒྷྻར༂࿡༞྄ྶ༈࿗ྫྷཚྸྯཇ༣ཥ࿺༕ྠ༵࿪྘ྭོྀ༐྾࿍༫ྉ༉ྲྀ༝࿭྾༫ཟབྷ཰༥ྭ༮཭ྣ࿁ཚ࿄࿯ༀྡཷཛའ࿯࿀࿱༒࿶༘༶࿿༤༅ཡྲྀ࿎ངྉ༳ཧབེཧ༑཯཯࿮࿌ྰ࿪ཱྀཕ཮དྷ࿻༨࿪༎࿘࿠࿄བྐ༆࿧ྫྷ༛༚྄གྷཉ༬ྴཫྡྷ࿽ྌ࿀ཱུ࿃ཱུྔ࿐࿠ཻྫྷྥ༑ན༦ྨགྷ༌ྛཊ༳࿫࿹ྸཕ༂ླྀྡྷགྷྺ࿢࿿༰ྷྸ༏ཅྀཽཌཝ༾ྨ࿪࿬༫ྨ࿪࿩ྴྲ࿓ྉཽྜྨ༟ཛཱི༈࿃཰࿥༫འ࿏ྔཪ༆࿀࿯཈࿟ཥྡྷཽཾ྘༇༒ཫ༓ྐཱིཤ༸࿬࿜࿎࿉ཡཝ࿉ྯ཭࿫࿻཯༿཮࿎཯ཎ༏཭ྂདྷ྘ཟ྘ྺ࿄ཻ༹࿁ྐླ࿕༏࿋༼ཟྩ༖༬ཱུ࿒ྛ༒࿡࿬࿡ཱུ࿆༅༤ཛྍཿཎཽྱ༦ྷ༦༉ངལཙྯ࿏ྸ࿢ཾ༹ཛྲ࿱ཝ࿮༰ཡྚ༘ྐྵ࿮ྕ࿩࿍༾ཞ࿽༉ྷ࿊࿳ྻནྲ༻ཡ࿴ྒྷ༦༁ཬ༔༈༡࿥ྌྷ༴འཆྩ༆ྣ࿸་༪ྠ࿪༰༣྘ཱུཉཕ྾༚༫།ཛ࿬ཾ༣༓ྜྷ࿇༛࿭༥࿫༦༻࿩࿛ྞཀ༿༒཭࿦ྖྲྀ༿࿬ཞཎཕཻ༞༜ྉཆ༱࿬ཤྛྩ༳࿬ྭཔ࿋࿜࿘ྥ࿡༱༕ཁཱྀ༆཮༺ཽྃ࿳གྷཙར཯ྦབྫྷྯ༢ྚྜྷ྄བྷཉྜྴཝའ࿢࿜࿀འ࿶ཚ༗࿩༹ཪྵ༒༰࿿ྂ࿕ྻ࿐ྮྐྜྷབྷ࿹ྒྷ࿁ཬླ༵༥ྔ࿶࿿࿲྆ཆད཈࿳༢ཌྈཇ࿾༰དུ࿵࿪ྋྴཙ༴།ཽ༬࿩࿠ྖྵྌྌ࿭ུ༳࿒ོྷཻྗྯ༿༘࿤࿦࿳༢ༀ༮༆ཎཫ࿅࿥ཙབྷྒྷཧྥཤ༠྅༈࿉࿍༻ྣ༦࿘྽༊ྟ࿘࿜༙པང༺࿫ྫ࿭༗ཾ༟࿣࿯བཨ༯࿍࿀ྎ࿇ང༯ྜའམྐ༒༝࿬༇༹ཚྒྷ࿦༇࿙༝དྷྫྷ༆ྂ࿿ྂཁང༱ྵ࿋༇ྒྷྰ༝࿱༭࿭༗༪࿡࿲࿱ཐཚ཮༔༴༌ཷཇྷ࿢ྠྷ༏ྡྷྶ༳ཙླྀྙ࿍་ྙ༲྇࿅ྌྫ༷༞྅ྼ࿒࿹རྗ࿼ཱ࿺࿞པ༰ྊྂ༮ཱུླྀྲ༉༬༳ངྖཧ྽༩ཇ༳ྑྚ༣སྣ༣ྠ࿾཈ྡཋཿྨེྫྷྥ࿈༧࿆࿃༑࿎༄ྜྷ࿠ྩཱི࿔ྮྒྷྞ࿿ཇ༙༖྽࿱ྫྷཋ࿳ྊཱ࿏ཋ༦ྍ࿁ྕྒྫ༏ྂཎ༆ཛྷ࿥།࿥࿥༖ཐ༧ེཐཟྖྨྌྮ༑ྫྷ༠ཹ࿞ཽྥ࿱༻ྗ࿜࿮࿈࿆཰༒༯༺༥ྐྫཻ࿍࿹ར༘ྻ࿏བྷ༗ྫྷ༎༺྾࿿མ༾࿾༼࿹ྤ࿁྇ཾཛྷལ༎ༀ࿝ཻྵྑ༉ཱྀ࿋ང༱༈ུ༂ཌྷ࿴༊ཿ࿃དྷ༅ོྖ࿘༔ལ࿅ྞཾྒྷྈ࿼༦ྼ࿦ཎདྒྷ༧ྭྭ࿲ད༂ཌྷ༭࿎ྃ཮ྛ༵࿍ཚ༨ཇ༢ླཷྍ࿯ཻ༒༰྽ྲྀ࿘࿥༉༱ཞཙ࿆ཊཌྦྷ࿸ྒ༼ྎྂྡྷྵྱ༉ྚཛྷ༻ྱ྽྆ྡེ࿜༰ནྊ࿼࿜བྷྤྦྷབྷ྄ྒྷ࿀࿺༲ེ༧྄ཨཞ࿞࿫ྒ༰࿉ཱུྻ࿤༿སཿྑྀ༢ཽཁ༮࿑࿎࿘࿌࿴࿹྘ྂ྅࿖྇ྒ༡༬༄྇༫࿯࿏༅࿷࿎࿙཈࿐དྷ࿄࿙࿷༺ཆཱྀ࿯༓ྶ༷ྉལཱིཏ༱࿕ླ༱༽ླྟ࿢ྛ༆༢༄༞࿟࿣དྷཞྎ཯ཎ࿪ྑ࿩༖༝ཤ཰࿮རྉ༬༅ཧ࿋ེ࿝࿲ྲྂཝ༿࿴ཎཆྊཛཾགཀྵཇྤཿ࿺༣༦࿼ྫྷྸཇ༤ྜ࿔༮༮࿲྄ྏབོ࿻༱࿙ྮ࿺࿽࿾༉ཕྍམཊཅཪྫྷ༴ྕ༮༄༘་ཎ༥ངྑཾྃ༸࿔༃༜ཬཧྲ༓࿀ྊ࿑༅࿲ླཚྭྂཛ࿅࿶ཋཱུ࿕࿐࿛༼཯ཙངྐ཰༦ཆྟ༠ཊ༞྘གྷྟཙཫ྾࿉འ࿓࿏ྭ༬ྞ༾࿯࿞ྍགྷ཈གྻ࿁༁༧ྷ࿝ཎ࿖༷ཥྲ༰༤࿧࿦༲ྊ࿑࿻དྷ཮ཫ࿯ས༼ཿཀ࿳࿏༌ྵྱཐ༆ད༤྄༥࿍࿺࿉ྫ࿻ླ༎༫࿙༙༅ྲས࿮གཟ཯༙ཥྈ༝༢ྼྮ࿛࿓ྵཻྂ࿱࿱࿰࿿࿨ལླྀ༡ྴ༥༄ཉཏ࿽ཱཐྫྈ༉༿࿏ཱཥྥྫ༽༗࿐༘࿊༂༛ཌྷྦྯ༣࿱ྶ༫༒࿑࿕࿉࿷ྸ༈࿒ལཎཛ྾࿤࿦ྗྀའ྄཮སྺ࿒༩࿁ྲྫཙཧ࿧࿚༹ྫ་༱བྷྂ༪ཆ࿜༔ྩྔ཮འ࿯࿍࿜࿇༇་࿋྘࿼ྡ࿼࿟༚ྐྑྃ࿍࿹࿔མྒྷ༉༏࿾࿅࿍࿢྾࿿མ༾࿩༓༚ྤྌ༴ྈཾ༚ཌ࿣༮༻༮ཱཱིི༼࿹࿰༄ིགྷཥྜྷ༦࿦༯༾࿘཰གཀ༉༕ཱྀ࿑ླ༆࿯࿽༎ཱིྀ༦ྊཐྙ࿴༯ྎབ༩ཛྷ࿌ྼ࿆ྨྗ༚ྫྷྠྣ࿯དྷ࿟ཥབྷ཯࿤ྀ༞༰ད༩ྯྼཅྲ༳ཞ༚࿼༅ཤཥ࿦࿃༯༣༠ྌ࿏࿑࿋༘྽ྒཛྷྛ༨ཫ༭༇ོྲྀཅབ༳༘༱࿰ལཱི༩࿌༐༶࿥྇ཙ༙ྰ྽࿢༒࿺࿞ཾ࿄࿈྘࿁ཾ࿛࿳࿿ཎྣ༑཰ྟ༤༳࿗࿕༸ཱྀཷ༶ཡྕ༯࿭ཫ༏࿷ཿ༅ྱ࿎࿶཈࿐ཀ࿙༢࿙ིཙཱྀ࿯࿓ཤ༷ྉ࿰༬་༱࿂ཾ༱༽ླཏ༕ྛ༒ཉ཰࿄ཇམ࿆གྷྠ༓ྱཟ࿢ྙཅ༽࿥ཅ༥༼ཏ༦ྥཛགྷཬ྿࿲࿥ཞཫ༮ྊ༝༗࿷ཇཛྷ࿟༜࿵༆࿋࿽࿅ྛ࿋࿈༐ི࿋࿕ལྜྪལྲྀྑཡ࿲༳ཱྀཫ࿯ྐྵ࿜࿹྽ྖཁྊྚཋཿའ࿪ྕྣྯཅ༷༣༛࿨ང༗ྎ࿋དཎ༜ྑྜྷ༄ྈཾ࿔དྷ༅ཫ࿈࿽༻༱༶ཝཾ་ླ࿼༦࿈࿺འྣལ࿱༬ྭ་࿎ཙླ࿑ྜ࿥࿸ུ࿤༓࿱࿞ྊ༈࿘༣ཾཫ࿯࿯༰ༀྔྈ࿥࿵ཀྵྜ࿻ྙཤ༤ངཿྋྞ༏ྋ༓ུ༢࿤ཆ࿱ྜ࿈ཾ࿌ྒཅ࿏ྑ࿜ྲྀྃ࿀༳࿯ཙཷ༬༬ཏ༛༧ཛ࿉ྚ༾ྛགྒྷ༑ྑ༄ྊཔ࿷ཎམྵྏ༃ཁཛྷཱྀེ྆༣ཋྪཌྷ྄ྦྷ࿋༅༙ཾ༗ོ༬༣ལྗ࿪ཋ࿫༘ག཮࿆ྐ༻ྗཥ༿ཛྷ࿱࿣༼༷࿣ྲྀ྅࿌࿖ྥ࿠ྻ༂༥ཱཱྀ࿝༪ཿ༓༺ྸཚཫ༨྇྅ཅ༵ྖྡྷྕཁྒྷཋྻྗ࿀࿿࿔ྲཡཐ༼ྜྷ༥ག༯༗ྠགྷ࿽ོ༹༶པ྆ཚ༸ེཋ࿛࿣ི༳ྜྷཉ࿖཰࿙ཌྷ།ྜ༌࿴༥༂།༶࿎࿂༡࿫࿈࿊ཁ࿮࿅༘༪࿭࿓࿥࿿࿲ྼ࿥࿀ྐྵ࿝ྂཌྷྩང༸ྸྚྋཱཱིི࿢༬࿹༇ཱྀ༔ཋ࿺ྺྦྷམ྽࿭ཾ༝ཛྷ࿺ཽ࿆༦ྡྷྦ࿪྄ྂ࿽ྯད࿂༁྽࿕ིླྀ༙ཹ྘༒ྞྩ࿶ི༿༰ྺ༻༾༑࿲྅༠ྮདྷྦྥྩ༤༠༚྘࿗࿓࿏༟༈ཐ࿎༵ྔ༝ྤ࿗ཚྟོྭཿ࿳ཇ༓༘ཛྷ࿿༗༴༐༇༱༫ཱི༣ྪ༱༏ྌ༤ོ࿋༙࿌ོཔཀྔ࿙༞ཥཛ༮༂༝࿈ྑཛྷ࿱ཧཛ༙དྷ༥༧༎ྛ༒཈࿿࿵ལ༔࿍࿥ཬ࿀༝ྫ༤ྥ࿘࿣࿳༗༊༪ླ༴ྡྷ࿋࿼࿜གྷ࿘ཏྦ༽ྪ༛་རྡྜྷྕྭ༌༡་ཹ࿸࿦࿈ཉ༔ྗ༳ྐྵ཈༵࿯༺༐༷༝࿥࿁྇།༲࿋࿕࿱ྪ྽༳༘བྷ࿊ལདྷ࿏࿤།ཅྖ྽ཬྩཾྤ࿧༰ྴྛྵྏ༹༺༛༧࿿༮༑༸༎྇༳༭༎ཱྀཫཁ࿷࿜࿹༊༪དྷ࿒༣࿃྽ྀ࿪༨ྣ࿂࿁࿕དྷུ༡༝༙࿋࿱ཱྀ༘ྸཱུྵ࿻ཱུ༼ཾ࿛྅࿡࿅༖࿐࿐༻ༀ༵྾མཾྙྥ༷ཬ࿂྅༠༒࿐་ྻྒ༚࿃ུ࿼ཝ྽ཞྥ་࿞࿜࿟࿅ཱྀ࿶ྡༀྸྱ཰ྂ࿁ར༶ཌྷ་ན࿫྘༵༭ྗྦ࿳༩༎ྑ༅ཿ࿁࿗ཞ༚ཛྷཾ཰࿓཭྽࿲ྙྤ࿆࿜ྸ࿸࿖࿌ྎ࿆ྣྷ༷ྵ࿩࿘࿔࿐ྖཱྀ༓༨།ཉ཯༔ཽ࿚གྞ࿁༶ༀ༫࿋ཾ༥ཅཱིྩ࿌༣༣࿺༾࿞࿨࿢ཀྵྪཬྦྷྰ༔ཊྌཫ྇ྡཐ཭གྷ࿽ཛྷཽ࿐ྷ༻ྪ࿸྿༳༐࿥྘ཡྎཬཟ༳࿩࿼༵གྷ༉༆ཌ࿑༞ཾཫ༣ཀ཯ཽཀ࿯ཆ༄དྷྻྥས༧ཷྯ༃࿈ཡཬྨ༭࿧༼ྱ༫༿࿯࿥༞ཿཫ༰࿀ཥ࿞༑་ྌ྘࿼࿳༐࿜༏ྐ࿇༹࿴࿹༅༶སྏབ༷࿙࿋࿪ྃ࿭༂࿅ྌ࿘༠༕ྥཽ࿜཮ྃཤྡྷ༸ྏྦྷ༛༱࿬དྷྎ༳ཱ࿐༆ྉྋ༇ཱྀག࿈ྣ༊ༀ࿮ཿ࿐ྋ༘ྥ༵༈࿰࿰༿࿅࿝ུབ༯཰ྂ࿉༓དང༞ྔཙ཭༜༅ྡྸྱྐྵ༇༃ྺེ࿎ྭོྕ࿎༚ྞ࿼ཇ༥༼ཆདཎནཱིཥྜྷྼྣདྑ༷ྱ࿁་༗༕࿈ཾ཰ྥ࿞༇ༀམྲྀྃ༒ྶ༦ཽངྦ࿔ྻ࿧ྯྲ༝༶࿔་༡ྒྷ࿘࿍ླྀ༉ྗྌཬྂྌཤ࿉ྊ༨ྙྲྀ༿༥ཪཱ༎࿫࿧༄བར཭࿌࿓རསྞཤཾཾ།ྍ༿༊࿸ྙྒ༞ཅཁྡྷ࿋༦༺ྗ྄༷ྉྵ༅࿭࿰༮ྠ༱༽ཛ࿢࿢ྛཿོ༱཯࿽༪དྷཞྎ࿹࿑࿪࿄ྃ࿂ཅ༤࿜༐ཐ྄྿༙ཆཌྷཅནྏ࿻༙ྐྵྯ࿪࿟ཆ࿈༆མ࿆༞ཨ࿓ླྀ༈ྈ྅ྯ࿒ྸ࿟࿵༌ར࿀ྒྷ༲࿖࿜ྷྼྵཱྀཫ༿࿮༒࿹཈ྌཿ༰࿿ྈ࿃ཅ༈࿲࿬࿍༑༷༣ཐྩངཏ༯࿆༯ྲ༐࿢༬ྔ྄ྜྥ࿴༮࿡༾༈ྫྷ༦༆ཇ༒༵ཛྷ࿴༣࿬ྰ༡ཱི༼྿࿱ྙ࿂དཅྜྟྦ࿧ཱཱྀུྰ༡ཷ༭དྷ྄༃࿐ྦྷ྇࿑ྡྷྌ࿍ྋ༭༬༑ཷ࿗ྜ༚྘࿗ཤཱྦ࿶༷༣༕ྭྴཪ࿚࿮࿥༯ཪྨ༂ྖྫྷྫྐྵྒྷ༸࿈ྻ༩༧ཊྦ༬ྺྯ࿔ེ༛྄ཙ༣࿌ྩའཀ࿊༃࿙཯ྤ༧ཇ༻དྷ࿳࿿༭༮༑࿼ླྩ༖࿿༜࿫྅࿓࿋༹࿢࿊࿱༆༳༕ྞ༜ོྻྰ྽࿐࿄ཻླ༨༨༿༣࿄གྷ࿮༙࿌ྚ࿾࿕࿆ྎ྇ྐ࿽࿥ཀྵ༊྘༰࿻ྉྼ࿓ཎ࿓྅ཝ༕ཾ༔࿳༿ཏཋྻ༑྿ཷ༖࿹ྭྙ༼༳ྒྷག༯ཏཛྷ࿻྾ཨཐ࿏པྨླྀྨེ࿢༢ྕྊ༮ཻྒ࿿ཪ࿧༗༜࿹ྪྔཊ༘ྜ༂྘ྺླྀ࿾༽ྤ࿰࿤ྰ࿡ཁ༌ྤྖ཮༢༔࿯ྌ࿤༎༞ཧྎྺྎཡཊྛྏ࿇࿈࿝༣༽࿺ཋྫྷ༎࿟ྡ࿮ༀམ࿧ཬ༺༕ཁ࿎སཻྪ཯࿕ྉང࿜ཀ࿩ྻེྸ࿸ྭ༳཭ྒྷྕྃ࿰༨ཇ࿤ྏ༦དྷ࿈྇༞༰ཾཿ࿘࿥࿅ྣ࿰ཌ࿖ྸཌྦྷཬྉབྷབྮྈ༠༇ྖྉ཯ླྀྱ༺མ࿶࿵༒ཿཚན࿉༔༩࿄࿔༽༯࿍࿬ྣ࿨༈ྲ࿒།༙࿶ྭྸ྿ས࿮ྰ࿇ྤྭྫླྀ༝༢ྼྮ༘࿪ྜྷཻྩྲ༠༣ྦྷ࿻࿂ཁ࿝ྊ࿉࿍ཷན࿒ཋ༦ཫ཯༴ཉཱྀཕ࿙༨༇ྑ࿋༄࿀ྜྷཿུ࿦ྶ༄཰༠༬འ༚࿪༎࿻ྍ༮࿹ྀ྆༇ླྀཿ࿸༳ྏཪཨ࿟ཱུ༎࿥༝࿥࿁྇ྴབ࿋༬ཞྪ༝ྑ༉༐཰ོ࿍ཇྡྡྷ༶༆ཛྷྊྙཾཛ࿋࿦༢ྛྔ༰༟࿅༫࿇༙࿴࿀ྷ࿍ྐྵ༤༢༮ྸ༻ྛྊ཯ྺྴྶྻ࿁࿾ཋ༘༢ྌ༶ཱིཤམ༷ྂཌྷ࿨ངཡ࿱྿༚༒࿕ྑྜྷ༄ྈཁྡྷ༃༅ྑ࿽ྌཛྷ࿼གདྷྤ༝༺ཧ༙ཧ࿎྽ཱི༳࿱ྙྵ࿌༐༘ྎ࿵ྩྃ཮ྛ༵༏ཡྼཇ࿯྇࿬ཱྰ༻༉ཛྷ࿔࿱ཇཆ༦ྪརབྜྷ྅༄࿦ྑྎོ༧ྔླཆ༢཯༰ཝྏའ࿤ྃ࿑཯࿷༿࿲ྲྀྂ࿋་࿯ཙུནྵ࿝ྉ༯࿯࿉༶࿕༘༫༩࿈པ࿌ཟཕྐྵཱཱྀུྌ཮༘༢࿈࿯ྷ࿑࿎࿓ཀྵ࿖ུྵཡ༩ྯཱྐ࿂࿷༣ཫ࿗ༀྀྔ༗༔ཱུཿ༏དྷ࿤ྟཆྟ࿫࿭ོ࿠ྱ࿆࿇࿘དྯྉ࿔༭༱༈ྖ࿥ཹྛ༿ླྦཹ࿢ཪ༃ྯ྇ྍ࿛༔ྕ࿆࿣༒࿥ཅ࿀ཱི࿚༬དྷ༸གྷཬ࿕࿷༏ྨལདྷ࿲࿤༮༊ླ༇ཿྨེ༭༊ྴམ྘࿭ད࿙ཾ༳࿔࿌༐༬ཀྵརམྚ༛ཌྷ྘࿞࿻དྷྤ༹࿳ཨ࿡༑༌ཏཚ࿘ྊ࿃ྪྎ࿷࿊࿓࿋༗ཌྷ࿬ཎ༘ཙཱྙ࿙༛༎༻࿕ྴ࿛࿪྽༂ཱུ༓ྉྕ࿟༭ཹ࿳ཧ࿛ཛྷུ཈༁༳ྺཡཱིྮཏཨང࿽ླྀྣཝ྘ཀ༿࿧࿄࿥࿗ཁ྆ཎཨ࿲ཪཡ࿑཰དྷ༐ཎ༧༫࿇཈࿧ྒྷྚི࿂༡༯༣࿦ེཚ࿑ལཕྖཻྕ࿭ྐྵ཭࿬ཫ྾྘ྜ࿮ྜ࿸࿀྿࿂ྣྲྀ༵༿༆ྉ࿡༛ཙྡྋཁ࿣ྷ༉࿅࿐཯࿺཭༝ྱྈཫ༎ྲྀ༿༥༄༼༹ཌྷྋ࿱ཷ༐༿࿌ྒྵཻ༱༄ྡྷླྀ༮ྫྐྵ྽࿲࿰ྟཤཪཽ༵ཷ༏࿯ྦྷཅ྇ྟ࿨ྯ࿕ཷ༠ཪཙ࿳ཐ྆༢དྫྷཪ༸ྴ༆ྨྫྷྸྞ༭ྟྑ༪ྜྷ࿋༝ཏ࿣྇ར༲࿋࿗ྭ༐࿢༠ཥྲ࿊ཝ࿯࿺༞ཆཚཕ༶྇༛ྐྵཨ࿮༈༽࿍༖༇ྉེ࿌ྻ࿚࿭༮༸࿓࿫࿭༶ྉྋཇ࿐཈࿒།ཛྡྷ༕ཇ༟ཀྒ࿲ྒ࿒་ཀྵཽ༷༩࿾ྂངྸྷཀྵ࿆࿢ན࿅༱༗྄ཱི཈࿈༎ྍྡམཿའབྷཬ༺༒ཛྷ࿴࿥༓ཏ཯࿕ཟཇ࿊ད༦༐ཿ༯༔ྲྀྃ཮྽༘ྥ་྄࿢ྍ࿘ཧ࿘ྡༀ࿹༦཰ྂཛ༁༂ྂ༚༤࿫྘ཆཤུ࿘ག༐ྯ࿪༌ི࿲ྯྥ࿶ཅ࿘ཌ༾ྶ༁མ༢་༫ྍ࿭ོ༬ྜྷྲ࿭༦ྷ࿝ཱྒ࿿࿖༦ྞགྷ࿄༴༗࿜࿄༕༭༄ཇ༻ཎྡྷ༨࿍དཎ༎༄༚༹ཌྷ༚྅ཷ࿦ླྚྒྵ࿣࿶༄ྡྷཇ༱༵࿑࿃༃࿰ྟྻ࿬འཽས࿥࿷རདྷ྘࿉ཀྵ࿜༒ྸ࿥༕྿ཛད཰ཷ༸ཱུ࿟࿀࿛ྑ༒༢༩༒ེཎ༵࿗ཟྭ༃࿬ཱཐ༠ཞ༚࿹࿫࿅ྊརི༠༯༉ྲ཈ༀ࿰࿟ྶྎ༘༌࿜ྈ༻དྷ࿤ྜ࿴྽༷࿣༳༧༠࿬ྯྡྷྡྷ༆བ࿪ཤྯ༉࿹࿟ཇྺༀཻ࿡༑ོ࿈ྏདྷ࿣ཚགྷ༌࿯༥ེང༜࿿྘࿆࿹࿓ཅ࿨ཹཷ༜ྖྃ༡ྤ࿋࿒༓འ྘བཛ࿅ཅ༃ྍ༙༎ཻཏ཯ཥ࿩࿨དརལ࿻༒ནཛ࿚ྃྈༀ࿡࿄་࿡༎ཪཻ྆༞ཛླྀ࿣ཎ་༏ཁྻ࿛ཥདྷ࿠ཧ࿖ྲྀ༠࿢ཆ༵༫༏࿦བཚ࿑ྔླཅ࿶༇࿿༾཭༺ྡྷ༢ཱྀ࿼ྥྗཿཤཌྷ࿕࿺༜ཷ༧ྤྵ྄ཨྥི࿫དྷྱྚྫ࿶ཪཎྔྤ࿓ད༕ྱ༮ྻཱུ࿴ྤ࿫྅བྷྛ༑ྍ༳࿵༅཮ྶྪ༡ྜྷཽཻྡྷཟ࿸མ࿳࿭ཝ࿃཈࿷ྡྷ࿋༦࿜ྗྡ༷ྉ྅༚࿼ད༛ྤ༬༢ྀ༾࿢ྛ࿮ཿ࿫ཹ࿯༶༒྅཭༾༑ཇམ༏དཎ࿎ཅ༼༧ྦ࿜༛༖༷ཝྔ༭࿴྆ཇ༷࿽࿑ྸཌ࿁༵࿯ཱྀྫ༘ྡ࿜࿤༼࿻ྲྀ༦ཾ༳ཱྀྻ࿝ྎ཰༹ྖྚ༱༿༦࿞ུྱཉགྷ࿮༾࿾༝࿹ྤ࿳཭༽༕༖ྸ࿈࿝༣ླ࿨ང࿭ྸད࿝པ༥ྡྷྜྷ཈༟༣࿪ླྣ࿛࿞ཪདྷ༗༆ཇྥཱུ༵ལ࿧཈༎༦࿬༲ྐྵ༸༄ྪ཈ྔྏཧ༖࿪ྒྷྕ཯༅ྱླཱུ࿫༿ྖ༾྇࿁དྷ༥ྨ༭ཌྷ༰༫ྉཟ༤࿧ྒྷཐོ༥࿮ྀྐ༪ྭ༪༓࿚ཟཤཨ࿯ྨཀྒ཮ྫྷྫྷ྽࿎཯ཤཱུ࿊༠ྷ࿹༬ྷ࿝྇ྦཀྵྂབགུༀ༢ྯ࿢࿑࿙ྊཐ࿟༝ཱཁ༽࿝࿴࿧࿧྄ྵ࿾ྙ྅࿼ྦ༁༺࿰࿈༷ཙཚ༎༇ྞ༜ྔ࿆༭ཿརཋྫྼྒྐྵྜྷ࿚ༀ༹࿲ྛྜྷྜྮྮ࿺ྶ༂༤࿣ྻ཰༠ྼ༰࿟ྮཨཉྴ༝༖༼࿒࿑࿪༝࿾ཡྗ࿬མ༐ཐྒྦ༙ཆྜ࿙༠࿶ཌྷ྆ྐྵྯ࿺༊༖ྴཋ༢࿲༏༾ཉཿྕ༔༮࿼࿁༚༺༫ྫ༲࿍࿀࿧ྜ࿑ཞེ༷ྨ༙྇྾༉࿿࿮༾࿾༆࿹ྤ༊ྏྑཀྸསༀ࿝ྂ࿟࿨ང࿿༩࿆࿦ྫ༧ྑྜྷ࿛ྡྷྣ࿪࿣༠ྀྡམཿཱུཧྗ༺༞ོཷ༙࿬࿯࿣ཱི༚྿ྻྭྊༀ༂ཌྷ༔ཧ࿀཮྽࿶࿟་ཋ࿑࿟༃࿩ེྶཷ࿪ྕ࿊࿝ཪ྘༩࿮།བྷ༥࿌༯ྲ࿍ི༐༗ྞ࿰ཫ࿤༅࿚ཹ࿈ཾ༙཈ཝྡྷྌ༈ྯྃ࿋ཐ࿯ཙྸ༖ྔ࿗ྭ࿕ཛ࿉࿢ྖ࿨ི࿫ྥྤ༮༈ཻཫླྀ࿊ྤ༓ཧདྷྱ༮࿹྇࿠࿜ྋྚབྷྛ༒ཧ༳࿵ནྑྩ༳༽࿋ཽཻ༅྾གྷོ཈࿐ཝྍཉ༑ྑ࿱྅࿯࿓༘༷ྉཱིྶཏ࿼࿊ཾ༱༽ྪཅྍ࿭࿳ཽྃྒཛ༞྇ྺ࿽༕༵ཎ࿯ྭ࿼࿬ཻༀ༫ྷ࿾་ྶ࿂࿴࿒ཐ༱྘ྭ༪ཞ࿞ཾཻྃླྀཽྥོ࿻ཱ࿜࿞༈྆࿱࿁༥࿟༚ྐཟ༹࿴࿹ྲྀ༿࿉࿁྘࿀࿙࿋༰ཀ࿹ྡྷ༰ྫྷཀ༌༥ྫྷ࿘ྊ༑࿀ྦྷྀ༵ྂ༛༛ཌྷ࿬དྷྚཙཱ༚ླྀ࿴༥࿅ཧ༔࿛༵ཕ༂ཱོུ༄ྏྠཅ༈࿪ཧཻྜྷུ཈༛ྦྷ༜ནྺྮཏཨྩཐ༚࿆༕࿿༆ྠཤྥེ྾༃࿩ྞཱྀ༷࿪ྕ྅དླྎ࿼༓།བ༯༼ཀྵྦྷཙ༤ི༐࿰༉࿍༢ྃཛྷྴ༆࿙࿳࿿༾ྟཧ༿྾྘༼ཱུཐོ࿝࿝ཡ࿨ྲྀ༵ྱ༆ྉཕ࿴ྒྷཱུ࿹࿣ྏྷ྾ྻ༃ཅསྌཉ࿷ༀ཮༫ྜྷཱུྻ࿛ྵ࿦࿊࿭࿼༸༡࿵ྞ࿳࿊ྺ༊ཡ࿪༌༸࿀ཪཽ༵ྱཝ࿅ྎ࿈ྃ༳࿫࿲༼࿷ཱི༢ྩྱ༐࿐ཊ༫ཱི༞ཀ࿼༳ཱུུ࿏ྷཅཇ࿬ཁཁ࿘྽࿈ཽཁྭ༆༃ི࿓ྶཱི༞ྸྲྀ࿞༷༤࿗ྰ༱༏ྡྭ྿࿤༘࿃྇࿤༒ྃྡཊ࿜༄࿇༩ཌཁ྄༹༘ངྤ༬༙ྯ࿝༽ྉྦྷ༚༵འ༦ཎཻྯ࿮ྉོ༖༧ཛཕ༝༺༨ྴ༄ྔ༣༔ྉཀྵྲ࿧༰༸༞ༀ༁ྖ༧࿱ཫཇ࿪ན༛ྼྐྵ༇༔࿐࿻࿅ྺི࿷྅ཱྀྊགྷཱཱིིྠ྅࿻࿺ྷ༁༂༢༞࿙ྶི࿗ཽཚྸ༣ཇྮཥྦྷ༕ེ༵࿪བྭྡྷྀུྱ༐ུྉ࿈ྲྀཅ࿭༓ུྑབྷ཰ྋྭྂ཭༚༘པ࿑࿯ྈྡཀྵཛོ࿯࿧࿱༒ཿ༘ག࿿༟་࿆ད࿎༁ྉྶཧ༰ྤ࿋༑཯ྥ࿮༱ྰཪ࿊ཤ཮དྷ༱༨࿒༎࿑࿠࿪ྐྐ࿮࿧ྴ༛༳༡ཐྀ༬ྗཫོ࿽༑࿋࿒࿃ཱུ༜࿐བཻཀ༑ཫན༦࿐གྷ࿹ྛ྽༳ྭ࿹ྸྑ༂ྞྡྷྋཌ࿃ྙ༰ྷྸ࿀ཅའཽཨཫ༾ས࿪࿋༫࿎༰ྎ༇ྲཽྉཽྜ࿾༟ྖཱི༈࿞཰༎༫࿘ཛྷ࿗ཪ༆࿧࿯࿛࿟ྗྡྷྱཾ྘༰༒༶༓ཛཱི༤ྸ࿬ཀ࿎༠ཡ༵࿉གྷྡ࿫࿦཯ཪ཮ཱ཯༺༏཭཰དྷ཰ཟ࿭ྺ༿༲ཻ཈ྐ༻࿕༙࿋࿖ཟྩྒྷ༬࿲࿒༣༒༶࿬࿡ྣཱུས༤ཛྍ࿍༺ཽ࿡༦࿚༦ྣ།࿉ཙྯྠྸ༞ཾ༟ཛཙ࿱ཝཱ༰ནྚྫྷ࿙ྴྕ࿩࿌༾࿰࿽྾ྷ࿊࿳ྻུྲྞཡཱྀྒྷྙརཬྫྷ༈ཕ࿥༶ྷྠཚཆ༲༆࿆࿸༅༪࿜༰༰ྛ྘࿈ཉཙ྾ུ࿆།ྤ࿬࿣༣༆ྜྷཟ༛࿭࿔࿫༩༻ྫ࿛ྞཀ༿࿄཭༱ྖཚ༿བ࿱ཎྒཻག༜༐ཆ࿆ཧཤ༣ྩ༷࿬ྣཔྯ࿜࿘࿛࿡ྚ༕࿊࿊༿༊༺༱ཽཚགྷ཯ར཯ྦབ༨ྯ࿮ྚ྄ུ༩ྀྜ༰ཝཱུ࿢༃࿋ོ࿶ཚ࿰࿩ྦཪྱ༃༨ྙྂ࿐ྻ་ྮ༰ྜྷ࿫ཆྒྷ࿶ཬ༻༵ྦྷྔ࿟ྙ࿲࿹ཆྯ཈༨༢ཌྈཇ࿕༰ུ༙࿫࿪ྋྴཙ༉།ྱ༬༖࿠ཨྵྌ࿞࿭ཱི༳࿚ོྷཻྗ࿍༿ཾ࿤࿸࿳༭ཾ༮ྫྷཎཹ࿅྾ཙབྷྒྷཧཀཤལ྅ུ࿉࿍༻ྣྃ࿘༘༊ན࿘࿜༙པབ༺྘ྫ༂༗࿯༟࿣࿣བྞ༯ྃ࿀࿝࿇ང༯ྜ࿲མྦྷ༒༘࿬༇ྩཚ༌࿦ྜྷྐྵ༿࿜ྫྷྏྂཌྂ༝ང྘ཙ࿋ཚྒྷྌ༝ཚླྀྲ࿚༪ྱ࿲྅ཐ༘༊༇༴༌ཐཇ༗࿢ཪ࿗࿻ྡྷྶ࿗ཙ༭ྙ࿄་࿿༲྇ྱྌྍ༷࿽྅ྕ࿒࿹྘ྗ྘ཱྼ༪༻༰ྊ༩༮࿪ླྀཎ༉༬༳ངྀཧ࿛༩ྗ༳༠༛༣࿔ྣ࿼ྠ༿཈ྡཋ྽ྥཔ࿂༭࿆ཿཧ࿰༺྄࿣ྰནླྀ࿹ྭ࿬ྻ༩ང࿎ྲྀྛྞཧདྷ࿄཈༇ྚྈ༒ྃ࿅࿃ཎདྫྷཱུྻྍར࿲ྦྦ༂࿋࿡࿂྅༽ྐྵཨ༐ྊ༪ཱུ༶ཁྯྙྍའཞ༌ཌྷཅ༫༃࿲ྙ༩༯ྶ࿹࿆༲ཱིྚ༸࿺ྒ྇ྞྊ࿈࿰࿶༜࿈ྷ࿹࿧࿛࿳༨ྔག༆ྎྊ༙ྵ࿫༵ཏ࿮ྵ࿓ང྾༚࿡࿨ླྀཙ࿢ྥ༣༳ྜྷའཱུ༚ཻ༓࿬྽༝ཀྙྊ༨྽࿆༴༺༞ྟཪྵཀྵ࿺ྯ࿞ྻ༤࿿༕࿂ཱྀྠྛ༙࿄཈࿙༜࿑༒࿍ྞྉཎ࿼ྑཛ࿚༝ཊཅ྄ྦྞ࿔࿴ྲྀ༗ྫ།ཏ༐࿪࿏༫ྥཅྲྀྴ࿂འ༌྿ླྀ࿙ཿདྷ༴༆༩ཌ࿼༿ྐྚུ࿀࿏࿺༶྽༕༭༳༗࿞ཱ࿈࿿༱ྕ཮པ༴࿾༱༆࿚ྌ཈ན࿍࿈༎ནྵྀ࿿ཝ༅༜ཱ༹༆࿢ྑ࿎ྯཡ༔མ༅࿫༓࿭྇ཎཫྞ࿲༵༟࿆࿳༭ྜྷ࿷࿔ྜྷྐྡྷྯ࿛ྂ࿄྄ཱིཐ༩༳ྛ༄ེྕཪཕ࿤༝ྥྞ࿉ླྀརཁདྔདྷ࿣ཅྰ࿗࿠༸ཋྯགྷ࿠།༎ད༫ྡད༺࿑࿟ྴཷག༓ྃ༾࿶༒࿴༴࿲ཤཔ༹࿄ྩཌྷ࿷࿀ྴབྷ༫༽བྷཨ࿔ྫྷ࿞࿒ི྾࿧ཛྷྍ࿒༖࿾ཌྷ཈ༀཎ༼྅༣ྨ༎ྒྷ༮༿ྲྛ༸༅ཅཱ཭༰༥ཞྫ༜ྡྷ༼༅ྯ༘༰༔༙༕ྗྔ༵ྃཙ࿼༵࿖࿡ུ༻ྐྱ༯࿒རྀུ࿽ཝ༩ཱིུ།ཚན࿁࿓ཷ༝࿯ཋ࿸༵ཛ྽ྮྼདྷཹཇུ྇࿉༅࿧࿛གྷ༛ྙ༪བྷ࿊ེྮལ࿑࿛ྐྵཥ࿑࿜࿻ེྩ༒཰྄࿄࿱྽࿨ཪༀཌྷ༻ྪྃདྺྑབྦྷ࿔འཛྷ࿢༑཈ད༉ྉ࿒࿺࿌༸༊ཁྥྼ༉༣༜༄།བ༛༫ྲྀོ༅༪༿࿅ྀྜྷྺྰ࿓ྡྷ࿿ཀྵྼ࿃ྱཽ༖༧ྗྺ༈ཫན࿍࿲༷ྷུྤ༜ཅ࿹ནཊ࿸༂࿽ཕཤ༞ྙྖཛྷ་ྮ࿓཰ཬོཝྡ࿈ྡྷ༄ྮཛྷྖ༔༇༯ཱིབ࿒࿧ཁ༦཭ཱི༡༱ྂ࿕ྮ࿫ྤྞཪ༻࿤ཾྌེ࿉ཉཚཾཧཌ࿜࿙ཪགྷྈ༸ྛྯ༎ཷབ༎࿋཯ྡང༺ཀ༘༉ཐཫད༙྆ྍ༃཰ྼཚ࿎࿞༹࿁ྩྩ༆ྲྀྴཀྵ༺ཟཀྵྖྪ࿷ྰཛྷ༞༒ཧ࿿࿙མ࿱༖࿠࿛࿱ཎྡྷ྅࿭༖༷༌྘཭ཙྮ࿺་༡࿸ཉ࿪༊࿱ྍ࿗࿳༚་࿬࿁࿪ྕ࿚༕༓༌ྡྷ༙ྲཱྀྡྷ࿖ྱ༫࿅བ྾࿕༊རྀིུ༶ྂ༳ྲཛྷའཱུ࿁ྟདཾཻ࿄ༀ࿪ྕ࿯ྛ༔࿜ྰ༾༩༫ཐ་࿀࿑༎༱ན࿏༛ཱྀྤ࿆ཷཀ࿛ྍ࿵ཀདྷ࿊ྤཌྷ༃༄༡࿹࿱ཿ࿠࿛࿃ྩྠྜ༓ཧྋ༡ྐཆྪ࿈ོ༩࿜࿧࿀࿷ྦམྸ༠ཌྷ཮ཾ༑༔࿷࿭ྙ࿭࿺ྦྚ༳དཛྷ་ཫ࿯༻ཉུཌ༕ྟ࿳༜࿉ྫྷ࿶࿡ྫྷ྆ཐ༓ཌ༞ྡྷྙ࿻༰࿥྅༫པནིཆ࿗༟ཥ࿵ིྍྻི࿿ྴ࿏ྒྷྂྟ༮༂་ྈླྀ࿳࿳ྣྛ࿈ཛགྷ༇༐ྲྦ࿡࿀࿣༄࿎ཙྤ࿉༦༚࿆༣པ༽ཻྠ཯ༀཫྤཐྀའༀྉཌ༑ྑ࿛࿽྅྽ྒྷ࿫࿋ྶ༮ྐྵ࿀ྣ༻࿬༒ཋྈ࿷༛ཝཻ༙༾ྍྥ࿻༔༰༷࿭༟ཀ།ྉཬད༴࿉࿎࿇ྭྖ࿕༔༕ྊཹ࿉࿬ཛྷ࿙࿏ཞ྆ར༘༴࿜࿳ྷ཰ྎ࿥༖ྭཊྵྛྒྷཆ཮ཥ༻࿈ོ༗྄ྷྊ༸ྒྷ༏࿣༹༴࿱༪࿓༯࿳ྯཱི༦ྡྷ࿱ྱ༳࿓ྦྕྪྡྷ༲ཉྜྷ༶ྥ༦ཤཙཚ࿒࿿࿛࿅ཐༀཪ࿑ཥ༰༔༿ྣ༢༑༕ྗྞ༳༱ཆ࿋ིྶབྷ༜ྌྚ༲ྞ༮࿻ཋ༿ཕ࿾ཋ༒ཱྀ༻ྉྥ༮༽࿙࿰ཾར཈࿃ྉྖ༐ཫ࿬ཏ྄ཌྷྋ࿕ཱོོུདྷ༘࿀ྱྣ࿏ྸཷཨ࿃༝༒ྕཚ཰྅཰ླྦ༧ྜྷཧཱུཆ༪ཁ༪ླ༫ྔྈ༴ྊྔ࿂༉ཕ཭༨ྨ࿂࿓࿿ཹྷྙྃ࿪ཤྙ༳ྖ࿗༪ྸྷ࿠ྏ࿅༶ྑགྷ࿔༜༨ོ࿺༮࿅࿼࿵ཉག༻࿳࿲࿠ྣམླཱི࿮༯ཙཌྷཱུ࿋ཁ࿼ཏྵཕ࿉༄ཏ༮ྣྞ༢ཻ༓཯ཿ࿘༻ལཨ࿿༝࿇࿚ྥ༈཈ིཡ༩ྒྷ࿬࿋࿥࿌ཌྷྵ࿧࿤༻༘༒࿟࿟ྱ༧༪ྦ࿍࿅ྐྵ༑࿬ྕ༵࿥ྥཊ༟།།༴ཧ༴ཐ࿎ྑ༹༭༯࿲ྈྊྌྐད༵༊ཛྷྺྨ༟࿁གྷདྷྊ࿗࿼་ཤ༖࿫ྩུ࿄༅࿹ྑྏ༭࿲ྐྵ༗࿙྅༵༸࿺༏ཻྛྼ࿚࿞ྟ࿩࿲ྲྀྜྷ༵࿈࿝༉ྜྷ྾ཌྷ༢࿔༖༹ྖ༳ཹ༶༄༎ྵྕ࿒ྺ཈༾ྲྀཿཪ཯ད࿲ྼཿ࿫ྗྥྈ༆ྜྷྜྷ࿶ཆད࿘࿥࿉ྷ࿒ཐྃྞ྘࿍࿟༿࿶༿࿟༃࿴ྠྦ༑༮ྒྻྔཁ༁࿁࿛།ྀ༚࿻࿧ྋྒྦགྷ༯࿏ཚྸཎ࿯࿧྾ཌྷཛྷཆལ࿫࿶྽༃༢ཬ࿼྅༩ཻྩཕྲ࿬མ࿹ྈཿེཨཙ࿰ག࿷༵༗བྷྲྀྍ࿷༨སབྷྟ྅༶࿻ཡ࿴༵࿎༫ྜྷཛྷྃ༸࿗࿨࿵ཱཹ༽༎཮༜࿮ཱུ༸ྭ༾༣ྏྠྰྠྊ࿈༮࿫ཚཨ༎࿡ྦྷཙྩཛདཁ཰ཥ༫ཕབྷ࿼ྜ྘࿫ྡ࿹༘ཨ࿄ཁ࿟ྠ༧ླ྆྽࿰༗༃༽࿁ིྙྊ༅ྛྲྀ༷ྩྦ༫ྯ༩ེཌྷ༑࿤࿄྾࿌࿞བ࿻༓࿙࿜཰༢࿪ྶྥ࿨࿟ྐང࿡࿬ྕ༱༳ྫ༱༭༚ྫྷག༵༈࿫དམ཮ོཙས༹࿣༃ྥཱ༜༄ས࿎སྣ࿁༫྘༅༸ྫ࿵ྖ࿳ྐྺ༊ཡ࿪༯༸༏ཪ࿪ཽ࿱ཫ࿅࿚࿈࿋༳ྑ࿈༚࿷ཱི༾ྩཽ༐࿇ཊཨྲ༞༈࿼ུ༷࿳࿏ྪཪཇ࿧ཁ࿁࿘༘࿈ཽཁྭ࿳༃༪࿓ཱི༷ྚ༸ྲྀཫ༷࿂࿗ྈ༱࿴ྡྭ࿍࿤ཿ࿃࿔࿤༺ྃྡ࿼࿜ྭ࿇ྮཌ࿽༲༘༊ངླྀ༬ྫྯ࿝༽ྉ༼༚ཚའ࿙ཎ࿣ྯ࿮བོ༅༧༅ཕ༝༺༨࿮༄ན༣༖ྉཀྵྲ࿧ྡ༸ྈༀཊྖྲཞཫྴ࿪༗༛༞࿙༴༔࿐༱࿅྅ི༌྅ཱྀྊགྷ࿥ཱིླ྅ྲྀ࿺ྪར༂࿓༞ཟྶ྿࿗ྫྷཚྸྭཇ࿭ཥཨ༕ེ༵࿪༣ྭ࿒ྀ༙ྱ༐ུྉོྲྀཿ࿭࿰ུཟབྷ཰༅ྭ࿆཭࿩༘ྡ࿑࿯࿤ྡལཛཞ༿࿴࿱༒࿶ི༘࿿༶༅ིྲྀ࿎༁ྉ༳ཧཉྤ࿋༑཯༞࿮࿌ྰཾ࿊࿔཮དྷཱྀ༨࿪༎ྤ࿠࿘བྐ࿓࿧ཽ༛ྍ༡༛ྀ༬ྫྷཫ࿲࿽ྨ࿋࿒࿃ཱུ༷࿐༟ཻཀ༑ྊ༜༦ྸགྷསྛ༐ྜྷ࿼࿹ྸཕ༂ཛྡྷ༳ྺ࿫࿿༰་ྸ࿍ཅ࿝ྫྷྺཝ༾ྒྷ࿪ྯ༫࿭༰༯ྴྲ࿵ྉ༢ྜ࿹༟ྒྲ༈༞཰༎༫ྡྷ࿏ྺཪ༆྘࿯࿁࿟ུ࿳ཏༀ྘ྼ༒༪༓༑ྲ࿂ྸ࿬༺࿎࿂ཡིཀྵ༟ྡ࿫༏཯ཾ཮ྺ཯ཎ༏཭ཐདྷྛཟ࿼ྺ༿༲ཻ࿁ྐྖ࿕࿴࿋༼ཟྩྦྷ༬࿒࿒ཋ༒ཻཧ࿡༣ཱུྸ༤ྡྍྌ༺ཽ࿡༦ྙ༦ྟ།࿉ཙྯའྸཫཾ཈ཛཱི࿱ཝ྾༰ཌྚ༳࿙ྴྕ࿩࿉༾ྜྷ࿽࿼ྷ࿊࿳ྻྜྷྲླཡ༏ྒྷ༜རཬ཭༈ྒ࿥༴࿗྾འཆ༮༆࿭࿸ཽ༪ྤ࿪༰ྭ྘མཉ༷྾༜ུ།ཱུ࿬༿༣ྵྜྷ࿇༛࿭༐࿫࿫༻༻࿛ྞཀ༿༑཭༤ྖ༷༿࿬ཞཎྒཻ༑༜཈ཆ࿆ཧཤ༣ྩཙ࿬ྛཔྯ࿜࿘࿤࿡྿༕ྃ࿊྇཮༺࿋ཽ࿲གྷ྘༁࿮ཌྷབཇྯ༴ྚདྷ྄བྷཉྜ࿮ཝ༵࿢཯࿀༜࿃ཚྺ࿩࿠ཪ࿲༒༰࿿ྂ࿩ྻ༌ྮ༡ྜྷ࿫ཆྒྷ࿇ཬཉ༵ཾྔ࿃࿿࿲ྪཆ༏཈࿳༢࿰ྈཇས༰ཧུ࿴༰༚ྴཙ༆།༔༬ྍ࿠ཛྵྌ༑࿭གྷ༳࿳ོ࿒࿣ྗཧ༿ཅ࿤྽࿳༢ༀ༮ྫྷཎྈ࿅༄ཙབྷྒྷཧཀཤ࿉྅ཱུ࿉࿍༻ྣ༠࿘ཁ༊ྏ࿘ྥ༙པ།༺ྣྫྒྷ࿚ཪ༟࿣཮བྀ༯࿽࿀ྎ࿇ང࿺ྜམམ࿆༃࿯ཧ༇རཚ༸࿦཭ྐྵ༵དྷྫྷ࿏ྂ࿿ཻྂ།༤ྵ࿋༇ྒྷྰ༝࿶༭མ༗༪࿷࿲࿰ཐཷ༊༇༴༌࿌ཇན࿢༔࿗࿨࿳ྶ࿗ཙླྙ༶་࿿༲ེ྇ྌ༡༷ྈ྅ྼ࿒࿹ཌྷྗ༣ཱྒྷ࿞ྡ༰ྊ༩༮མླྀྖ༉༬༳ངྀཧཿ༩ྏ༳༃༛༣࿔ྣྭྠ཭཈ྡཋ྽ྥཔ༧༭࿯ཿཧ࿰༺྽࿣༶ན༲࿹ྣ࿬ྻྉངྵྲྀཟཔ༏དྷ࿄࿄༇༧ྈྜ࿴ྗ࿃ཎ࿀ྫྷ༵ྻྥ༁࿙ྦྦྗ࿋ྕ࿂ྴྒ࿂ླ༐࿮༪༰༶༺࿧ཚཕའྶ༌༟ཅ࿘༃ྡྷྙ༩སྶ࿩࿆࿞ཱིྣྸ࿺ཪ྇༭ྊ࿔࿰࿤ན࿈༅࿹༏࿛ཫ༨ྔག༆྆ྊ࿉ྵ࿇༵༥࿮ྵྟངཬ༚཭࿨ླྀཙ࿢༕༣࿱ྜྷ࿍ཱུ༜࿣༓བྷ྽ཻཀ࿸ྊྫྷ྽࿆࿈༺ྈྟཱྀཙ༠࿺ྯ࿄ྻ࿉࿿༹࿂࿻ྠྛ࿋࿄࿯࿙࿓࿄ྒ࿻ྞ།ཎ྘ྑྙ࿚༝ཊཅ࿙ྦ࿈࿔༕ྲྀ༼ྑ།ཏ༐༻࿏གྥཅྲྀྴྩའྜ྿ྸ࿙ཿདྷ༴༆༩ྷ࿼༝ྐྚུ࿀ྊ࿺༕྽ཝླྀགྷ༗࿞ྱ࿈࿱༱྆༊ྤ༴࿾ཀྵ༆ྙྌཷན࿍࿈༎གྷྵླ࿿ྲྀ༅འ༲ཱ༆࿢༡࿎྘ཡ༔མ༅࿫༓ཊ྇༃ཫྞ࿲༵࿼࿆ྞ༭ྑ࿷࿕ྜྷྐྞྯ࿯ྂ༆ྲ࿇ཐ༩༳ྛྣེ྅ཪྖ࿟༝ྥྞཷླྀརཁདྔདྷ࿣ཅ༞࿗བ༸ཋྯགྷ࿠།ྜྷད༫ྡད༺࿑࿟ྴཱྀག༓ྃ༾࿶༒࿴༴ྖཤཔ༹࿄ྩཌྷ࿷࿀༴བྷ༫༽བྷཨ࿔ྫྷ࿞࿪ི྾࿧༵ྍ࿒࿱࿾༹཈ཐ༺࿈ཡ༣࿔༎࿐༮ྩྲ࿭ྸ༅ཅཱླྀ༰ྪཞ༻༜ྡྷ༖༅༘ྃཛྷྕ༜ྰྗྔ༵࿋ཙༀ